mapper.update:
UPDATE t_order
SET pay_url = #{payUrl}, update_time = NOW()
WHERE user_id = #{userId}
  AND out_trade_no = #{outTradeNo}

UPDATE t_order
SET status = 5, update_time = NOW()
WHERE user_id = #{userId}
  AND order_id = #{orderId}
  AND status = 1

mapper.select:
SELECT id, order_id, user_id, goods_id, goods_name, goods_image_url,
       original_price, deduction_price,
       pay_price, status, market_type, create_time
FROM t_order
WHERE user_id = #{userId}

    AND id < #{lastId}

ORDER BY id DESC
LIMIT #{count}
